// Merge analysis results with enriched context from webhook
const analysis = $('HTTP Request - OpenAI Analysis').first().json;
const webhookData = $('Webhook - CI Failure').first().json;
const contextMeta = webhookData.contextMetadata || {};

// Use actual data passed from github-app
const existingAnnotations = webhookData.annotations || [];
const testFailures = webhookData.testFailures || [];
const prMetadata = webhookData.prMetadata;
const workflowTiming = webhookData.workflowTiming;
const dependencyChanges = webhookData.dependencyChanges || [];

// Get AI-generated code annotations (from the analysis)
const aiAnnotations = (analysis.codeAnnotations || []).map(ann => ({
  path: ann.path,
  startLine: ann.line,
  level: ann.level,
  message: ann.message,
  title: ann.title || ''
}));

// Merge existing annotations with AI-generated ones (AI annotations take priority)
const allAnnotations = [...aiAnnotations, ...existingAnnotations];

// Build enriched analysis object for Slack and GitHub
const enrichedAnalysis = {
  repository: analysis.repository || webhookData.repository,
  confidence: analysis.confidence || analysis.confidenceScore || 0.5,
  analysis: analysis.analysis || analysis.summary || 'Analysis unavailable',
  identified_cause: analysis.identified_cause || analysis.identifiedCause || '',
  recommended_actions: analysis.recommended_actions || analysis.recommendedActions || [],
  // Enriched context from github-app
  checkName: webhookData.checkName,
  headSha: webhookData.headSha,
  // Combined annotations (AI + existing from check run)
  annotations: allAnnotations,
  testFailures: testFailures,
  // PR context from actual PR metadata
  prContext: prMetadata ? {
    number: webhookData.pullRequests?.[0] || prMetadata.number || 0,
    title: prMetadata.title || '',
    author: prMetadata.author || '',
    branch: prMetadata.headBranch || '',
    baseBranch: prMetadata.baseBranch || '',
    labels: prMetadata.labels || []
  } : null,
  // Workflow context from actual timing data
  workflowContext: workflowTiming ? {
    name: webhookData.checkName || '',
    duration: formatDuration(workflowTiming.durationMs)
  } : null,
  // Actual dependency changes from github-app
  dependencyChanges: dependencyChanges
};

// Helper function for formatting duration
function formatDuration(ms) {
  if (!ms) return '';
  const seconds = Math.floor(ms / 1000);
  const minutes = Math.floor(seconds / 60);
  const remainingSeconds = seconds % 60;
  if (minutes > 0) {
    return `${minutes}m ${remainingSeconds}s`;
  }
  return `${seconds}s`;
}

return [{ json: { analysis: enrichedAnalysis, webhookData: webhookData } }];

// Get the merged data from previous node
const data = $('Merge Analysis with Context').first().json;
const analysis = data.analysis;
const webhookData = data.webhookData;

// Get PR numbers (may be empty array)
const pullRequests = webhookData.pullRequests || [];

// If no PRs, return empty array (skip GitHub posting)
if (pullRequests.length === 0) {
  return [];
}

// Return items for each PR to post comment to
return pullRequests.map(prNumber => ({
  json: {
    repository: analysis.repository,
    pr_number: prNumber,
    analysis: analysis
  }
}));
